al s = p.Size if s.Z >= 1.2 and s.X <= 0.5 and s.Y <= 0.5 then return true end end return false end local function findArrowRoot(inst) if inst:IsA("BasePart") and isArrowPart(inst) then return inst end if inst:IsA("Model") then for _, d in ipairs(inst:GetDescendants()) do if d:IsA("BasePart") and isArrowPart(d) then return d end end return inst.PrimaryPart or inst:FindFirstChildWhichIsA("BasePart") end if inst:IsA("BasePart") then if isArrowPart(inst) then return inst end local m = inst:FindFirstAncestorOfClass("Model") if m then for _, d in ipairs(m:GetDescendants()) do if d:IsA("BasePart") and isArrowPart(d) then return d end end end end return nil end local function registerArrow(inst) if not S.HomingArrows then return end local arrow = findArrowRoot(inst) if not arrow or guided[arrow] then return end local cam = Workspace.CurrentCamera if cam and (arrow.Position - cam.CFrame.Position).Magnitude > 30 then return end local tgtPart, tgtModel = lastLockPart, lastLockModel if not tgtPart or not tgtPart.Parent or (tgtModel and isDowned(tgtModel)) then local best, bestM, bd = nil, nil, S.AimRange local origin = arrow.Position for model, e in pairs(AEntries) do if e.part and e.part.Parent and Enabled[e.sp] and not isDowned(model) then local d = (e.part.Position - origin).Magnitude if d < bd and hasLOS(origin, aimPoint(e.part), model) then bd, best, bestM = d, e.part, model end end end tgtPart, tgtModel = best, bestM end if not tgtPart then return end guided[arrow] = {untilT = os.clock() + S.HomingTime, targetPart = tgtPart, targetModel = tgtModel} pcall(function() arrow.Anchored = true end) end local function hookArrowSource(parent) if not parent then return end track(parent.ChildAdded:Connect(function(ch) task.defer(function() registerArrow(ch) if ch:IsA("Model") or ch:IsA("Folder") then for _, d in ipairs(ch:GetDescendants()) do if d:IsA("BasePart") then registerArrow(d) end end end end) end)) end hookArrowSource(Workspace) for _, n in ipairs({"Arrows", "Arrow", "Projectiles"}) do local f = Workspace:FindFirstChild(n) if f then hookArrowSource(f) end end track(Workspace.ChildAdded:Connect(function(ch) local n = string.lower(ch.Name) if n == "arrows" or n == "arrow" or n == "projectiles" then hookArrowSource(ch) end task.defer(function() registerArrow(ch) end) end)) local function guideArrows(dt) if not S.HomingArrows then return end for arrow, info in pairs(guided) do if not arrow or not arrow.Parent or os.clock() > info.untilT then guided[arrow] = nil continue end local tp, tm = info.targetPart, info.targetModel if not tp or not tp.Parent or (tm and isDowned(tm)) then local best, bestM, bd = nil, nil, S.AimRange for model, e in pairs(AEntries) do if e.part and e.part.Parent and Enabled[e.sp] and not isDowned(model) then local d = (e.part.Position - arrow.Position).Magnitude if d < bd then bd, best, bestM = d, e.part, model end end end if best then info.targetPart, info.targetModel = best, bestM tp, tm = best, bestM else guided[arrow] = nil continue end end local dest = aimPoint(tp) local pvel = Vector3.zero pcall(function() pvel = tp.AssemblyLinearVelocity end) dest = dest + pvel * 0.22 local pos = arrow.Position local to = dest - pos local dist = to.Magnitude if dist <= S.MagnetSnap then arrow.CFrame = CFrame.lookAt(dest, dest + (pvel.Magnitude > 1 and pvel or to)) guided[arrow] = nil continue end local speed = arrow:GetAttribute("Speed") if typeof(speed) ~= "number" or speed < 10 then speed = (Hunting.speed and Hunting.speed(S.AimStrength)) or 220 end speed = speed * 1.15 local flightT = math.clamp(dist / speed, 0.04, 0.8) local lead = dest + pvel * flightT * 0.55 local want = (lead - pos) if want.Magnitude < 0.05 then continue end want = want.Unit local look = arrow.CFrame.LookVector local str = math.clamp(S.HomingStrength, 0.2, 1) local near = math.clamp(1.8 - dist / 50, 1, 2.2) local runBoost = pvel.Magnitude > 4 and 1.25 or 1 str = math.clamp(str * near * runBoost, 0.2, 1) local blend = math.max(1 - math.pow(1 - str, dt * 60), 0.55 * str) local newDir = look:Lerp(want, blend) newDir = newDir.Magnitude < 0.05 and want or newDir.Unit local step = math.min(speed * dt, dist - 0.4) local newPos = pos + newDir * step arrow.CFrame = CFrame.lookAt(newPos, newPos + newDir) pcall(function() arrow.AssemblyLinearVelocity = newDir * speed end) end end local function hasBow() local c = LP.Character if not c then return nil end for _, t in ipairs(c:GetChildren()) do if t:IsA("Tool") then local n = string.lower(t.Name) if string.find(n, "bow", 1, true) or string.find(n, "hunt", 1, true) then return t end end end return nil end local function fireBowOnce() local bow = hasBow() if bow then pcall(function() bow:Activate() end) end end ------------------------------------------------------------ -- AIM ------------------------------------------------------------ local aimLock, aimLockSp, aimLockModel = nil, nil, nil local aimStatus = "off" local baseFOV = 70 local zoomFx = nil local shootAcc = 0 local function setZoom(on) Cam = Workspace.CurrentCamera if not Cam then return end if on and S.ZoomOnAim then if not zoomFx then baseFOV = Cam.FieldOfView local blur = Instance.new("BlurEffect") blur.Name = "MYWISH_Zoom" blur.Size = 0 blur.Parent = Lighting zoomFx = blur end TweenService:Create(Cam, TweenInfo.new(0.15), {FieldOfView = S.ZoomFOV}):Play() TweenService:Create(zoomFx, TweenInfo.new(0.15), {Size = 2}):Play() else TweenService:Create(Cam, TweenInfo.new(0.2), {FieldOfView = baseFOV > 10 and baseFOV or 70}):Play() if zoomFx then TweenService:Create(zoomFx, TweenInfo.new(0.2), {Size = 0}):Play() end end end local function pickTarget(origin, look) local cone = math.cos(math.rad(S.AimFOV)) local best, bestSp, bestModel, bestScore = nil, nil, nil, -1e9 local bestAny, bestAnySp, bestAnyModel, bestAnyD = nil, nil, nil, S.AimRange for model, e in pairs(AEntries) do if not (model.Parent and e.part and e.part.Parent and Enabled[e.sp]) then continue end if isDowned(model) then paintAnimalHL(e, model) continue end local at = aimPoint(e.part) local off = at - origin local dist = off.Magnitude if dist < 2 or dist > S.AimRange then continue end if not hasLOS(origin, at, model) then continue end local dir = off.Unit local dot = look:Dot(dir) local score = dot * 2.2 - (dist / S.AimRange) * 0.65 if dot >= cone and score > bestScore then bestScore, best, bestSp, bestModel = score, e.part, e.sp, model end if dist < bestAnyD then bestAnyD, bestAny, bestAnySp, bestAnyModel = dist, e.part, e.sp, model end end if best then return best, bestSp, bestModel, (best.Position - origin).Magnitude end if bestAny then return bestAny, bestAnySp, bestAnyModel, bestAnyD end return nil end local function aimStep(dt) if not S.AimOn then if aimLock then aimLock, aimLockSp, aimLockModel = nil, nil, nil aimStatus = "off" setZoom(false) end return end Cam = Workspace.CurrentCamera if not Cam then return end refreshLOSFilter() local origin = Cam.CFrame.Position local look = Cam.CFrame.LookVector local spd = Hunting.speed and Hunting.speed(S.AimStrength) or 200 local part, sp, model, dist = pickTarget(origin, look) if not part then aimLock, aimLockSp, aimLockModel = nil, nil, nil lastLockPart, lastLockModel = nil, nil aimStatus = "blocked / none" setZoom(false) return end if model and isDowned(model) then local e = AEntries[model] if e then paintAnimalHL(e, model) end aimStatus = "downed" aimLock = nil lastLockPart, lastLockModel = nil, nil return end local at = aimPoint(part) local vel = Vector3.zero pcall(function() vel = part.AssemblyLinearVelocity end) local predictT = math.clamp(dist / spd, 0.05, 0.9) local leadPos = at + vel * predictT local dir = Hunting.aimAt and Hunting.aimAt(origin, leadPos, spd) if not dir then dir = (leadPos - origin).Unit end if not hasLOS(origin, leadPos, model) then if not hasLOS(origin, at, model) then aimStatus = "behind tree" setZoom(false) aimLock = nil return end dir = Hunting.aimAt and Hunting.aimAt(origin, at, spd) or (at - origin).Unit end aimLock, aimLockSp, aimLockModel = part, sp, model lastLockPart, lastLockModel = part, model aimStatus = string.format("%s %dm", sp or "?", math.floor(dist or 0)) setZoom(true) local targetCF = CFrame.new(origin, origin + dir) local alpha = math.clamp(1 - S.AimSmooth, 0.2, 1) local blend = 1 - math.pow(1 - alpha, dt * 60) if Cam.CFrame.LookVector:Dot(dir) > 0.98 then blend = math.max(blend, 0.9) end Cam.CFrame = Cam.CFrame:Lerp(targetCF, blend) if S.ShootOnAim then shootAcc += dt if shootAcc >= S.ShootEvery then shootAcc = 0 fireBowOnce() end end end local aimMarker = Instance.new("BillboardGui") aimMarker.Name = "MYWISH_AIM" aimMarker.Size = UDim2.fromOffset(40, 40) aimMarker.AlwaysOnTop = true aimMarker.MaxDistance = 600 aimMarker.Enabled = false aimMarker.Parent = Vis do local ring = Instance.new("Frame") ring.Size = UDim2.fromScale(1, 1) ring.BackgroundTransparency = 1 ring.Parent = aimMarker local s1 = Instance.new("UIStroke") s1.Color = C.Rose s1.Thickness = 2 s1.Parent = ring Instance.new("UICorner", ring).CornerRadius = UDim.new(1, 0) local lab = Instance.new("TextLabel") lab.Name = "L" lab.Size = UDim2.new(2.4, 0, 0, 12) lab.Position = UDim2.new(-0.7, 0, 1, 2) lab.BackgroundTransparency = 1 lab.Font = Enum.Font.GothamBold lab.TextSize = 10 lab.TextColor3 = C.Rose lab.Parent = ring end ------------------------------------------------------------ -- TP DRAG TO PLAYER ------------------------------------------------------------ local tpDrag = nil local function stopTPDrag() local st = tpDrag tpDrag = nil if not st then return end local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") local root = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") if root then pcall(function() root.AssemblyLinearVelocity = Vector3.zero end) end if hum and hum.Parent then hum.WalkSpeed = S.SpeedOn and S.Speed or (st.savedSpeed or 16) pcall(function() hum:Move(Vector3.zero) end) end end local function startTPDrag(plr) stopTPDrag() local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") tpDrag = { plr = plr, untilT = os.clock() + S.TPTimeout, savedSpeed = hum and hum.WalkSpeed or 16, } end local function tpDragStep(dt) local st = tpDrag if not st then return end if os.clock() > st.untilT then stopTPDrag() return end local ch = LP.Character local root = ch and ch:FindFirstChild("HumanoidRootPart") local hum = ch and ch:FindFirstChildOfClass("Humanoid") local tRoot = st.plr.Character and st.plr.Character:FindFirstChild("HumanoidRootPart") if not root or not tRoot then return end local back = tRoot.CFrame.LookVector local flatBack = Vector3.new(back.X, 0, back.Z) if flatBack.Magnitude < 0.05 then flatBack = Vector3.new(0, 0, 1) else flatBack = flatBack.Unit end local dest = tRoot.Position - flatBack * S.TPStopDist dest = Vector3.new(dest.X, tRoot.Position.Y, dest.Z) local delta = dest - root.Position local flat = Vector3.new(delta.X, 0, delta.Z) local dist = flat.Magnitude local yDist = math.abs(delta.Y) if dist <= S.TPStopDist + 0.5 and yDist < 8 then stopTPDrag() return end local dir = dist > 0.1 and flat.Unit or Vector3.zero local yBoost = 0 if delta.Y > 2 then yBoost = math.clamp(delta.Y * 0.35, 0, 40) elseif delta.Y < -4 then yBoost = math.clamp(delta.Y * 0.2, -25, 0) end local speed = S.TPDragSpeed if hum then hum.WalkSpeed = 0 pcall(function() hum:Move(Vector3.zero) end) pcall(function() hum:MoveTo(dest) end) end local step = math.min(speed * dt, math.max(dist - S.TPStopDist * 0.5, 0)) local newPos = root.Position + dir * step + Vector3.new(0, yBoost * dt, 0) local look = dir.Magnitude > 0.05 and dir or root.CFrame.LookVector root.CFrame = CFrame.new(newPos, newPos + Vector3.new(look.X, 0, look.Z)) root.AssemblyLinearVelocity = dir * speed + Vector3.new(0, yBoost, 0) root.AssemblyAngularVelocity = Vector3.zero end ------------------------------------------------------------ -- RENDER ------------------------------------------------------------ track(RunService.RenderStepped:Connect(function(dt) local myRoot = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") for model, e in pairs(AEntries) do if e.part and e.part.Parent then local down = isDowned(model) if e.hl and e.hl.Enabled then paintAnimalHL(e, model) end if e.txt and e.tag and e.tag.Enabled then if down then e.txt.Text = "♡ " .. e.sp .. " down" e.txt.TextColor3 = C.HitRed else local bits = {"♥ " .. e.sp} if S.ShowPrice and SPECIES[e.sp] then table.insert(bits, SPECIES[e.sp].Price) end if S.ShowDist and myRoot then table.insert(bits, math.floor((e.part.Position - myRoot.Position).Magnitude) .. "m") end e.txt.Text = table.concat(bits, " ") e.txt.TextColor3 = SPECIES[e.sp].Color end e.tag.Adornee = e.part end end end for plr, e in pairs(PEntries) do if e.txt and e.tag and e.tag.Enabled then local char = plr.Character local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head")) if hrp then local friend = Friends[plr.UserId] local line1 = (friend and "🩷 " or "◆ ") .. plr.Name local line2 = "" if S.ShowDist and myRoot then line2 = math.floor((hrp.Position - myRoot.Position).Magnitude) .. "m" end local hum = char:FindFirstChildOfClass("Humanoid") if hum then line2 = line2 .. (line2 ~= "" and " · " or "") .. math.floor(hum.Health) .. "HP" end e.txt.Text = line2 ~= "" and (line1 .. "\n" .. line2) or line1 e.txt.TextColor3 = friend and C.Friend or C.Player e.tag.Adornee = hrp end end end pcall(aimStep, dt) pcall(guideArrows, dt) pcall(tpDragStep, dt) if aimLock and aimLock.Parent and S.AimOn and aimLockModel and not isDowned(aimLockModel) then aimMarker.Adornee = aimLock aimMarker.Enabled = true local L = aimMarker:FindFirstChild("L", true) if L then L.Text = aimStatus end else aimMarker.Enabled = false end end)) local wildStatus = "..." task.spawn(function() while true do pcall(function() local has, found = scanAnimals() local n = 0 for _ in pairs(found or {}) do n += 1 end wildStatus = (has and "OK · " or "fb · ") .. n end) pcall(scanPlayers) pcall(refreshLOSFilter) task.wait(S.ScanEvery) end end) track(Players.PlayerAdded:Connect(function() task.wait(1) pcall(scanPlayers) end)) track(Players.PlayerRemoving:Connect(function(p) clearPlayer(p) end)) task.spawn(function() while task.wait(0.2) do if S.SpeedOn and not tpDrag then local h = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") if h and math.abs(h.WalkSpeed - S.Speed) > 0.1 then h.WalkSpeed = S.Speed end end end end) ------------------------------------------------------------ -- BUILD MAIN GUI (hidden until intro ends) ------------------------------------------------------------ local gui = Instance.new("ScreenGui") gui.Name = "MY_WISH" gui.ResetOnSpawn = false gui.IgnoreGuiInset = true gui.DisplayOrder = 125 gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling gui.Enabled = false gui.Parent = PG for i = 1, 8 do local p = Instance.new("ImageLabel") p.BackgroundTransparency = 1 p.Image = ROSE p.ImageColor3 = (i % 2 == 0) and C.PinkSoft or C.Pink p.ImageTransparency = 0.4 p.Size = UDim2.fromOffset(math.random(10, 16), math.random(10, 16)) p.ZIndex = 1 p.Parent = gui task.spawn(function() while p.Parent do p.Position = UDim2.new(math.random() * 0.95, 0, 1.1, 0) p.Rotation = math.random(0, 360) local tw = TweenService:Create(p, TweenInfo.new(math.random(14, 24), Enum.EasingStyle.Linear), { Position = UDim2.new(math.random() * 0.95, 0, -0.1, 0), Rotation = p.Rotation + math.random(120, 300), }) tw:Play() tw.Completed:Wait() end end) end local Win = Instance.new("Frame") Win.Name = "Main" Win.Size = UDim2.fromOffset(280, 340) Win.Position = UDim2.new(0.5, -140, 0.42, -170) Win.BackgroundColor3 = C.Bg Win.BorderSizePixel = 0 Win.Active = true Win.ZIndex = 5 Win.Parent = gui Instance.new("UICorner", Win).CornerRadius = UDim.new(0, 16) local winStroke = Instance.new("UIStroke", Win) winStroke.Color = C.Pink winStroke.Thickness = 2 local Head = Instance.new("Frame") Head.Name = "Head" Head.Size = UDim2.new(1, 0, 0, 42) Head.BackgroundColor3 = C.Bg2 Head.BorderSizePixel = 0 Head.