xtXAlignment.Left l.ZIndex = 7 l.Parent = parent end local function card(parent, h) local r = Instance.new("Frame") r.Size = UDim2.new(1, -2, 0, h or 30) r.BackgroundColor3 = C.Card r.BorderSizePixel = 0 r.ZIndex = 7 r.Parent = parent Instance.new("UICorner", r).CornerRadius = UDim.new(0, 10) local s = Instance.new("UIStroke", r) s.Color = C.Line s.Thickness = 1 s.Transparency = 0.2 return r end local function addToggle(parent, text, get, set) local r = card(parent, 30) local lbl = Instance.new("TextLabel") lbl.Size = UDim2.new(1, -48, 1, 0) lbl.Position = UDim2.new(0, 8, 0, 0) lbl.BackgroundTransparency = 1 lbl.Text = text lbl.Font = Enum.Font.GothamMedium lbl.TextSize = 11 lbl.TextColor3 = C.Text lbl.TextXAlignment = Enum.TextXAlignment.Left lbl.ZIndex = 8 lbl.Parent = r local pill = Instance.new("Frame") pill.Size = UDim2.fromOffset(32, 16) pill.Position = UDim2.new(1, -40, 0.5, -8) pill.BorderSizePixel = 0 pill.ZIndex = 8 pill.Parent = r Instance.new("UICorner", pill).CornerRadius = UDim.new(1, 0) local dot = Instance.new("Frame") dot.Size = UDim2.fromOffset(12, 12) dot.BorderSizePixel = 0 dot.ZIndex = 9 dot.Parent = pill Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0) local hit = Instance.new("TextButton") hit.Size = UDim2.fromScale(1, 1) hit.BackgroundTransparency = 1 hit.Text = "" hit.ZIndex = 10 hit.Parent = r local function paint(on) pill.BackgroundColor3 = on and C.Pink or C.Bg3 dot.BackgroundColor3 = on and C.White or C.TextDim dot.Position = UDim2.new(0, on and 18 or 2, 0.5, -6) end paint(get()) hit.MouseButton1Click:Connect(function() local v = not get() set(v) paint(v) end) end local function addSlider(parent, text, min, max, get, set) local r = card(parent, 40) local cap = Instance.new("TextLabel") cap.Size = UDim2.new(1, -14, 0, 14) cap.Position = UDim2.new(0, 8, 0, 3) cap.BackgroundTransparency = 1 cap.Font = Enum.Font.Gotham cap.TextSize = 10 cap.TextColor3 = C.PinkDeep cap.TextXAlignment = Enum.TextXAlignment.Left cap.ZIndex = 8 cap.Parent = r local bar = Instance.new("Frame") bar.Size = UDim2.new(1, -16, 0, 7) bar.Position = UDim2.new(0, 8, 0, 24) bar.BackgroundColor3 = C.Bg3 bar.BorderSizePixel = 0 bar.ZIndex = 8 bar.Parent = r Instance.new("UICorner", bar).CornerRadius = UDim.new(1, 0) local fill = Instance.new("Frame") fill.BackgroundColor3 = C.Pink fill.BorderSizePixel = 0 fill.Size = UDim2.new(0, 0, 1, 0) fill.ZIndex = 9 fill.Parent = bar Instance.new("UICorner", fill).CornerRadius = UDim.new(1, 0) local function paint() local v = get() fill.Size = UDim2.new(math.clamp((v - min) / (max - min), 0, 1), 0, 1, 0) cap.Text = text .. " " .. tostring(v) end paint() local drag = false local function apply(x) local rel = math.clamp((x - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1), 0, 1) set(math.floor(min + (max - min) * rel + 0.5)) paint() end bar.InputBegan:Connect(function(i) if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then drag = true apply(i.Position.X) end end) track(UIS.InputChanged:Connect(function(i) if drag and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then apply(i.Position.X) end end)) track(UIS.InputEnded:Connect(function(i) if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then drag = false end end)) end local function addBtn(parent, text, cb) local b = Instance.new("TextButton") b.Size = UDim2.new(1, -2, 0, 28) b.BackgroundColor3 = C.PinkSoft b.BorderSizePixel = 0 b.Text = text b.Font = Enum.Font.GothamMedium b.TextSize = 11 b.TextColor3 = C.PinkDeep b.AutoButtonColor = false b.ZIndex = 8 b.Parent = parent Instance.new("UICorner", b).CornerRadius = UDim.new(0, 10) b.MouseButton1Click:Connect(cb) return b end local DragBtn = Instance.new("TextButton") DragBtn.Name = "DragAim" DragBtn.Size = UDim2.fromOffset(64, 64) DragBtn.Position = UDim2.new(0, 12, 0.58, -32) DragBtn.BackgroundColor3 = C.Card DragBtn.Text =