owDist = v end) addToggle(P_ESP, "Show price", function() return S.ShowPrice end, function(v) S.ShowPrice = v end) addBtn(P_ESP, "Rescan", function() scanAnimals() scanPlayers() end) section(P_Move, "SPEED") addToggle(P_Move, "Speed on", function() return S.SpeedOn end, function(v) S.SpeedOn = v if not tpDrag then local h = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") if h then h.WalkSpeed = v and S.Speed or 16 end end end) addSlider(P_Move, "WalkSpeed", 16, 200, function() return S.Speed end, function(v) S.Speed = v if S.SpeedOn and not tpDrag then local h = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") if h then h.WalkSpeed = v end end end) section(P_Move, "GO TO PLAYER (drag / run)") addSlider(P_Move, "Drag speed", 40, 160, function() return S.TPDragSpeed end, function(v) S.TPDragSpeed = v end) addSlider(P_Move, "Stop distance", 3, 12, function() return S.TPStopDist end, function(v) S.TPStopDist = v end) addBtn(P_Move, "Stop drag now", function() stopTPDrag() Footer.Text = "drag stopped" end) local tip = Instance.new("TextLabel") tip.Size = UDim2.new(1, -2, 0, 32) tip.BackgroundColor3 = C.Card tip.BorderSizePixel = 0 tip.Text = " tap a name to run/drag to them\n (no TP snap-back)" tip.Font = Enum.Font.Gotham tip.TextSize = 9 tip.TextColor3 = C.TextDim tip.TextXAlignment = Enum.TextXAlignment.Left tip.ZIndex = 8 tip.Parent = P_Move Instance.new("UICorner", tip).CornerRadius = UDim.new(0, 8) local playerBox = Instance.new("Frame") playerBox.Size = UDim2.new(1, -2, 0, 0) playerBox.AutomaticSize = Enum.AutomaticSize.Y playerBox.BackgroundTransparency = 1 playerBox.ZIndex = 7 playerBox.Parent = P_Move Instance.new("UIListLayout", playerBox).Padding = UDim.new(0, 4) local function rebuildPlayers() for _, c in ipairs(playerBox:GetChildren()) do if c:IsA("TextButton") or (c:IsA("TextLabel") and c.Name == "Empty") then c:Destroy() end end local any = false for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then any = true local friend = Friends[plr.UserId] local b = Instance.new("TextButton") b.Size = UDim2.new(1, 0, 0, 28) b.BackgroundColor3 = friend and C.PinkSoft or C.Card b.BorderSizePixel = 0 b.Text = (friend and " 🩷 " or " ✧ ") .. plr.Name b.Font = Enum.Font.GothamMedium b.TextSize = 11 b.TextColor3 = C.Text b.TextXAlignment = Enum.TextXAlignment.Left b.ZIndex = 8 b.Parent = playerBox Instance.new("UICorner", b).CornerRadius = UDim.new(0, 10) b.MouseButton1Click:Connect(function() startTPDrag(plr) Footer.Text = "running → " .. plr.Name end) end end if not any then local n = Instance.new("TextLabel") n.Name = "Empty" n.Size = UDim2.new(1, 0, 0, 18) n.BackgroundTransparency = 1 n.Text = "nobody else here" n.Font = Enum.Font.Gotham n.TextSize = 10 n.TextColor3 = C.TextDim n.ZIndex = 8 n.Parent = playerBox end end rebuildPlayers() track(Players.PlayerAdded:Connect(function() task.wait(0.5) rebuildPlayers() end)) track(Players.PlayerRemoving:Connect(function() task.wait(0.2) rebuildPlayers() end)) addBtn(P_Move, "Refresh players", function() refreshFriends() rebuildPlayers() end) section(P_Mobs, "SPECIES") for _, name in ipairs(ORDER) do local sp = SPECIES[name] addToggle(P_Mobs, name .. " " .. sp.Price, function() return Enabled[name] end, function(v) Enabled[name] = v for m, e in pairs(AEntries) do if e.sp == name then if not v then clearAnimal(m) else ensureAnimal(m, name) end end end if v then pcall(scanAnimals) end end) end addBtn(P_Mobs, "All ON", function() for n in pairs(Enabled) do Enabled[n] = true end pcall(scanAnimals) end) addBtn(P_Mobs, "Safe no Bear/Wolf", function() for n in pairs(Enabled) do Enabled[n] = (n ~= "Bear" and n ~= "Wolf") end for m, e in pairs(AEntries) do if e.sp == "Bear" or e.sp == "Wolf" then clearAnimal(m) end end pcall(scanAnimals) end) local Bubble = Instance.new("TextButton") Bubble.Name = "RoseBubble" Bubble.Size = UDim2.fromOffset(54, 54) Bubble.Position = UDim2.new(0, 12, 0.78, 0) Bubble.BackgroundColor3 = C.PinkSoft Bubble.Text = "" Bubble.Visible = false Bubble.ZIndex = 60 Bubble.Active = true Bubble.Parent = gui Instance.new("UICorner", Bubble).CornerRadius = UDim.new(1, 0) local bStroke = Instance.new("UIStroke", Bubble) bStroke.Color = C.Rose bStroke.Thickness = 2.5 for i, cfg in ipairs({{s=34,o=0,t=0},{s=24,o=-8,t=0.1},{s=24,o=8,t=0.1},{s=18,o=0,t=0}}) do local img = Instance.new("ImageLabel") img.Size = UDim2.fromOffset(cfg.s, cfg.s) img.Position = UDim2.new(0.5, -cfg.s/2 + cfg.o, 0.5, -cfg.s/2) img.BackgroundTransparency = 1 img.Image = ROSE img.ImageColor3 = (i == 4) and C.Rose or C.Pink img.ImageTransparency = cfg.t img.ZIndex = 60 + i img.Parent = Bubble end local bHeart = Instance.new("TextLabel") bHeart.Size = UDim2.fromOffset(16, 16) bHeart.Position = UDim2.new(0.5, -8, 0.5, -8) bHeart.BackgroundTransparency = 1 bHeart.Text = "♡" bHeart.Font = Enum.Font.GothamBlack bHeart.TextSize = 14 bHeart.TextColor3 = C.White bHeart.ZIndex = 70 bHeart.Parent = Bubble local function closeWin() Win.Visible = false Bubble.Visible = true end local function openWin() Bubble.Visible = false Win.Visible = true end XBtn.MouseButton1Click:Connect(closeWin) Bubble.MouseButton1Click:Connect(openWin) local function enableDrag(handle, target) local dragging, start, pos handle.InputBegan:Connect(function(i) if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging = true start = i.Position pos = target.Position end end) track(UIS.InputChanged:Connect(function(i) if not dragging then return end if i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch then local d = i.Position - start target.Position = UDim2.new(pos.X.Scale, pos.X.Offset + d.X, pos.Y.Scale, pos.Y.Offset + d.Y) end end)) track(UIS.InputEnded:Connect(function(i) if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging = false end end)) end enableDrag(Head, Win) enableDrag(Bubble, Bubble) task.spawn(function() while task.wait(0.4) do local an, pn, down = 0, 0, 0 for m in pairs(AEntries) do an += 1 if isDowned(m) then down += 1 end end for _ in pairs(PEntries) do pn += 1 end local dragTxt = tpDrag and ("run→" .. (tpDrag.plr.Name or "?")) or "idle" Footer.Text = wildStatus .. " · down " .. down .. " · " .. dragTxt end end) local function Unload() setAim(false) setZoom(false) stopTPDrag() for _, c in ipairs(Cons) do pcall(function() c:Disconnect() end) end for m in pairs(AEntries) do clearAnimal(m) end for p in pairs(PEntries) do clearPlayer(p) end table.clear(guided) pcall(function() if zoomFx then zoomFx:Destroy() end end) pcall(function() local intro = PG:FindFirstChild("MY_WISH_INTRO") if intro then intro:Destroy() end end) pcall(function() gui:Destroy() end) pcall(function() Vis:Destroy() end) if getgenv then getgenv().MYWISH = nil end end if getgenv then getgenv().MYWISH = {Unload = Unload} end ------------------------------------------------------------ -- SNOW BUNNY INTRO POPUP → then open GUI ------------------------------------------------------------ local function playIntroThenOpen() local intro = Instance.new("ScreenGui") intro.Name = "MY_WISH_INTRO" intro.IgnoreGuiInset = true intro.ResetOnSpawn = false intro.DisplayOrder = 200 intro.ZIndexBehavior = Enum.ZIndexBehavior.Sibling intro.Parent = PG local dim = Instance.new("Frame") dim.Size = UDim2.fromScale(1, 1) dim.BackgroundColor3 = Color3.fromRGB(40, 20, 35) dim.BackgroundTransparency = 1 dim.BorderSizePixel = 0 dim.ZIndex = 1 dim.Parent = intro -- soft snow dots for i = 1, 18 do local flake = Instance.new("Frame") flake.Size = UDim2.fromOffset(math.random(3, 7), math.random(3, 7)) flake.Position = UDim2.new(math.random(), 0, -0.1, 0) flake.BackgroundColor3 = C.Snow flake.BackgroundTransparency = 0.15 flake.BorderSizePixel = 0 flake.ZIndex = 2 flake.Parent = intro Instance.new("UICorner", flake).CornerRadius = UDim.new(1, 0) task.spawn(function() while flake.Parent do flake.Position = UDim2.new(math.random(), 0, -0.05, 0) local tw = TweenService:Create(flake, TweenInfo.new(math.random(25, 45) / 10, Enum.EasingStyle.Linear), { Position = UDim2.new(math.random(), 0, 1.05, 0), BackgroundTransparency = 0.6, }) tw:Play() tw.Completed:Wait() flake.BackgroundTransparency = 0.15 end end) end -- card local cardF = Instance.new("Frame") cardF.AnchorPoint = Vector2.new(0.5, 0.5) cardF.Position = UDim2.fromScale(0.5, 0.48) cardF.Size = UDim2.fromOffset(0, 0) cardF.BackgroundColor3 = C.Snow cardF.BorderSizePixel = 0 cardF.ZIndex = 10 cardF.Parent = intro Instance.new("UICorner", cardF).CornerRadius = UDim.new(0, 28) local cs = Instance.new("UIStroke", cardF) cs.Color = C.PinkSoft cs.Thickness = 3 cs.Transparency = 0.1 local scale = Instance.new("UIScale") scale.Scale = 0.4 scale.Parent = cardF -- bunny face (drawn with frames — pure white snow bunny) local face = Instance.new("Frame") face.Name = "Bunny" face.AnchorPoint = Vector2.new(0.5, 0) face.Position = UDim2.new(0.5, 0, 0, 18) face.Size = UDim2.fromOffset(120, 110) face.BackgroundTransparency = 1 face.ZIndex = 11 face.Parent = cardF -- left ear local earL = Instance.new("Frame") earL.Size = UDim2.fromOffset(22, 52) earL.Position = UDim2.new(0.5, -42, 0, -8) earL.Rotation = -14 earL.BackgroundColor3 = C.Bunny earL.BorderSizePixel = 0 earL.ZIndex = 11 earL.Parent = face Instance.new("UICorner", earL).CornerRadius = UDim.new(1, 0) local earLi = Instance.new("Frame") earLi.Size = UDim2.new(0.45, 0, 0.55, 0) earLi.Position = UDim2.new(0.28, 0, 0.28, 0) earLi.BackgroundColor3 = C.PinkSoft earLi.BorderSizePixel = 0 earLi.ZIndex = 12 earLi.Parent = earL Instance.new("UICorner", earLi).CornerRadius = UDim.new(1, 0) -- right ear local earR = Instance.new("Frame") earR.Size = UDim2.fromOffset(22, 52) earR.Position = UDim2.new(0.5, 20, 0, -8) earR.Rotation = 14 earR.BackgroundColor3 = C.Bunny earR.BorderSizePixel = 0 earR.ZIndex = 11 earR.Parent = face Instance.new("UICorner", earR).CornerRadius = UDim.new(1, 0) local earRi = Instance.new("Frame") earRi.Size = UDim2.new(0.45, 0, 0.55, 0) earRi.Position = UDim2.new(0.28, 0, 0.28, 0) earRi.BackgroundColor3 = C.PinkSoft earRi.BorderSizePixel = 0 earRi.ZIndex = 12 earRi.Parent = earR Instance.new("UICorner", earRi).CornerRadius = UDim.new(1, 0) -- head local head = Instance.new("Frame") head.Size = UDim2.fromOffset(88, 78) head.Position = UDim2.new(0.5, -44, 0, 28) head.BackgroundColor3 = C.Bunny head.BorderSizePixel = 0 head.ZIndex = 12 head.Parent = face Instance.new("UICorner", head).CornerRadius = UDim.new(1, 0) local hs = Instance.new("UIStroke", head) hs.Color = Color3.fromRGB(240, 230, 235) hs.Thickness = 1.5 hs.Transparency = 0.4 -- blush L / R local blushL = Instance.new("Frame") blushL.Size = UDim2.fromOffset(16, 10) blushL.Position = UDim2.new(0, 8, 0.55, 0) blushL.BackgroundColor3 = C.PinkSoft blushL.BackgroundTransparency = 0.35 blushL.BorderSizePixel = 0 blushL.ZIndex = 13 blushL.Parent = head Instance.new("UICorner", blushL).CornerRadius = UDim.new(1, 0) local blushR = Instance.new("Frame") blushR.Size = UDim2.fromOffset(16, 10) blushR.Position = UDim2.new(1, -24, 0.55, 0) blushR.BackgroundColor3 = C.PinkSoft blushR.BackgroundTransparency = 0.35 blushR.BorderSizePixel = 0 blushR.ZIndex = 13 blushR.Parent = head Instance.new("UICorner", blushR).CornerRadius = UDim.new(1, 0) -- eyes (start open) local eyeL = Instance.new("Frame") eyeL.Name = "EyeL" eyeL.Size = UDim2.fromOffset(12, 14) eyeL.Position = UDim2.new(0.5, -22, 0.32, 0) eyeL.BackgroundColor3 = Color3.fromRGB(55, 40, 55) eyeL.BorderSizePixel = 0 eyeL.ZIndex = 14 eyeL.Parent = head Instance.new("UICorner", eyeL).CornerRadius = UDim.new(1, 0) local sparkL = Instance.new("Frame") sparkL.Size = UDim2.fromOffset(4, 4) sparkL.Position = UDim2.new(0, 6, 0, 2) sparkL.BackgroundColor3 = C.White sparkL.BorderSizePixel = 0 sparkL.ZIndex = 15 sparkL.Parent = eyeL Instance.new("UICorner", sparkL).CornerRadius = UDim.new(1, 0) local eyeR = Instance.new("Frame") eyeR.Name = "EyeR" eyeR.Size = UDim2.fromOffset(12, 14) eyeR.Position = UDim2.new(0.5, 10, 0.32, 0) eyeR.BackgroundColor3 = Color3.fromRGB(55, 40, 55) eyeR.BorderSizePixel = 0 eyeR.ZIndex = 14 eyeR.Parent = head Instance.new("UICorner", eyeR).CornerRadius = UDim.new(1, 0) local sparkR = Instance.new("Frame") sparkR.Size = UDim2.fromOffset(4, 4) sparkR.Position = UDim2.new(0, 6, 0, 2) sparkR.BackgroundColor3 = C.White sparkR.BorderSizePixel = 0 sparkR.ZIndex = 15 sparkR.Parent = eyeR Instance.new("UICorner", sparkR).CornerRadius = UDim.new(1, 0) -- nose local nose = Instance.new("Frame") nose.Size = UDim2.fromOffset(8, 6) nose.Position = UDim2.new(0.5, -4, 0.52, 0) nose.BackgroundColor3 = C.Pink nose.BorderSizePixel = 0 nose.ZIndex = 14 nose.Parent = head Instance.new("UICorner", nose).CornerRadius = UDim.new(1, 0) -- cute smile (U shape via text) local mouth = Instance.new("TextLabel") mouth.Size = UDim2.fromOffset(30, 16) mouth.Position = UDim2.new(0.5, -15, 0.62, 0) mouth.BackgroundTransparency = 1 mouth.Text = "ᴗ" mouth.Font = Enum.Font.GothamBold mouth.TextSize = 18 mouth.TextColor3 = Color3.fromRGB(70, 50, 65) mouth.ZIndex = 14 mouth.Parent = head -- title local wish = Instance.new("TextLabel") wish.AnchorPoint = Vector2.new(0.5, 0) wish.Position = UDim2.new(0.5, 0, 0, 138) wish.Size = UDim2.new(1, -20, 0, 36) wish.BackgroundTransparency = 1 wish.Text = "MY WISH" wish.Font = Enum.Font.GothamBlack wish.TextSize = 28 wish.TextColor3 = C.PinkDeep wish.TextTransparency = 1 wish.ZIndex = 12 wish.Parent = cardF local sub = Instance.new("TextLabel") sub.AnchorPoint = Vector2.new(0.5, 0) sub.Position = UDim2.new(0.5, 0, 0, 172) sub.Size = UDim2.new(1, -20, 0, 18) sub.BackgroundTransparency = 1 sub.Text = "♡ snow bunny says hi ♡" sub.Font = Enum.Font.Gotham sub.TextSize = 12 sub.TextColor3 = C.TextDim sub.TextTransparency = 1 sub.ZIndex = 12 sub.Parent = cardF -- hearts floating for i = 1, 6 do local h = Instance.new("TextLabel") h.Size = UDim2.fromOffset(18, 18) h.Position = UDim2.new(0.5, math.random(-60, 60), 0.5, math.random(-20, 40)) h.BackgroundTransparency = 1 h.Text = (i % 2 == 0) and "♡" or "♥" h.Font = Enum.Font.GothamBold h.TextSize = math.random(12, 18) h.TextColor3 = C.Pink h.TextTransparency = 1 h.ZIndex = 16 h.Parent = cardF task.spawn(function() task.wait(0.4 + i * 0.08) TweenService:Create(h, TweenInfo.new(0.35), {TextTransparency = 0.15}):Play() TweenService:Create(h, TweenInfo.new(1.6, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), { Position = h.Position - UDim2.fromOffset(0, 40), TextTransparency = 1, }):Play() end) end -- animate in TweenService:Create(dim, TweenInfo.new(0.35), {BackgroundTransparency = 0.35}):Play() TweenService:Create(cardF, TweenInfo.new(0.45, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Size = UDim2.fromOffset(220, 210), }):Play() TweenService:Create(scale, TweenInfo.new(0.45, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1, }):Play() task.wait(0.35) TweenService:Create(wish, TweenInfo.new(0.4), {TextTransparency = 0}):Play() TweenService:Create(sub, TweenInfo.new(0.45), {TextTransparency = 0}):Play() -- cute face loop: blink + ear wiggle + bounce local bounce = true task.spawn(function() local baseY = face.Position.Y.Offset while bounce and face.Parent do -- blink eyeL.Size = UDim2.fromOffset(12, 3) eyeR.Size = UDim2.fromOffset(12, 3) eyeL.Position = UDim2.new(0.5, -22, 0.38, 0) eyeR.Position = UDim2.new(0.5, 10, 0.38, 0) task.wait(0.12) if not bounce then break end eyeL.Size = UDim2.fromOffset(12, 14) eyeR.Size = UDim2.fromOffset(12, 14) eyeL.Position = UDim2.new(0.5, -22, 0.32, 0) eyeR.Position = UDim2.new(0.5, 10, 0.32, 0) -- ear wiggle TweenService:Create(earL, TweenInfo.new(0.18, Enum.EasingStyle.Sine), {Rotation = -22}):Play() TweenService:Create(earR, TweenInfo.new(0.18, Enum.EasingStyle.Sine), {Rotation = 22}):Play() task.wait(0.18) TweenService:Create(earL, TweenInfo.new(0.18, Enum.EasingStyle.Sine), {Rotation = -10}):Play() TweenService:Create(earR, TweenInfo.new(0.18, Enum.EasingStyle.Sine), {Rotation = 10}):Play() -- little hop TweenService:Create(face, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Position = UDim2.new(0.5, 0, 0, baseY - 8), }):Play() task.wait(0.22) TweenService:Create(face, TweenInfo.new(0.28, Enum.EasingStyle.Bounce, Enum.EasingDirection.Out), { Position = UDim2.new(0.5, 0, 0, baseY), }):Play() task.wait(0.55) end end) -- hold then fade out task.wait(2.15) bounce = false TweenService:Create(wish, TweenInfo.new(0.3), {TextTransparency = 1}):Play() TweenService:Create(sub, TweenInfo.new(0.3), {TextTransparency = 1}):Play() TweenService:Create(scale, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale = 0.3}):Play() TweenService:Create(cardF, TweenInfo.new(0.35), {BackgroundTransparency = 1}):Play() TweenService:Create(dim, TweenInfo.new(0.4), {BackgroundTransparency = 1}):Play() task.wait(0.42) intro:Destroy() -- open main GUI with a soft pop gui.Enabled = true Win.Visible = true local pop = Instance.new("UIScale") pop.Scale = 0.85 pop.Parent = Win TweenService:Create(pop, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play() task.delay(0.4, function() if pop then pop:Destroy() end end) end -- boot task.defer(function() refreshFriends() local has, found = scanAnimals() local n = 0 for _ in pairs(found or {}) do n += 1 end scanPlayers() refreshLOSFilter() Footer.Text = (has and "OK · " or "fb · ") .. n print("[MY WISH] intro → GUI") playIntroThenOpen() end)
